import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapComponent from "../MapComponent";
import "./HousePredictionForm.css";

export default function HousePredictionForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    location: "",
    area: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    year: "",
    condition: "",
    latitude: "",
    longitude: "",

    hospitalApplicable: "",
    hospitalDistance: "",

    schoolApplicable: "",
    schoolDistance: "",

    railwayApplicable: "",
    railwayDistance: "",

    busApplicable: "",
    busDistance: "",
  });

  const [coordinates, setCoordinates] = useState({ lat: null, lng: null });
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const getCurrentLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        async (position) => {
          const { latitude, longitude } = position.coords;
          setCoordinates({ lat: latitude, lng: longitude });
          setForm((prev) => ({
            ...prev,
            latitude,
            longitude,
          }));
          const geoApiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
          try {
            const resp = await fetch(
              `https://maps.googleapis.com/maps/api/geocode/json?latlng=${latitude},${longitude}&key=${geoApiKey}`
            );
            const data = await resp.json();
            if (data.status === "OK") {
              const rooftopResult = data.results.find(
                (r) => r.geometry.location_type === "ROOFTOP"
              );
              setForm((prev) => ({
                ...prev,
                location: (rooftopResult || data.results[0]).formatted_address,
              }));
            } else {
              alert(`Failed to get address: ${data.status} - ${data.error_message || ""}`);
            }
          } catch (error) {
            alert("Error fetching location address.");
          }
        },
        () => alert("Permission denied or unable to get location."),
        { enableHighAccuracy: true }
      );
    } else {
      alert("Geolocation is not supported by this browser.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(undefined);
    setLoading(true);
    try {
      const response = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await response.json();
      setResult(data.price);
    } catch {
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  const renderFacility = (label, applicableName, distanceName) => (
    <div className="form-group">
      <div className="facility-label">{label}</div>
      <div className="facility-radios">
        <label>
          <input
            type="radio"
            name={applicableName}
            value="applicable"
            checked={form[applicableName] === "applicable"}
            onChange={(e) =>
              setForm((f) => ({
                ...f,
                [applicableName]: e.target.value,
                [distanceName]: "",
              }))
            }
          />
          Applicable
        </label>
        <label>
          <input
            type="radio"
            name={applicableName}
            value="notApplicable"
            checked={form[applicableName] === "notApplicable"}
            onChange={(e) =>
              setForm((f) => ({
                ...f,
                [applicableName]: e.target.value,
                [distanceName]: "",
              }))
            }
          />
          Not Applicable
        </label>
      </div>
      {form[applicableName] === "applicable" && (
        <input
          type="number"
          min="0"
          step="0.1"
          placeholder={`Distance from ${label.toLowerCase()} (km)`}
          value={form[distanceName]}
          onChange={(e) =>
            setForm((f) => ({ ...f, [distanceName]: e.target.value }))
          }
          required
        />
      )}
    </div>
  );

  return (
    <div className="house-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="house-predict-panels">
        <div className="property-details-card">
          <div className="property-header">
            <span className="icon">
              <img src="/icons/house.png" alt="" />
            </span>
            <span className="property-title">Property Details</span>
          </div>
          <div className="property-desc">
            Enter the details of the house to get an accurate price prediction
          </div>

          <form onSubmit={handleSubmit} className="property-form">
            <div className="form-group">
              <label className="form-label">Location</label>
              <div className="input-with-icon">
                <span className="input-icon">📍</span>
                <input
                  name="location"
                  type="text"
                  placeholder="e.g., Downtown, Suburb Name"
                  value={form.location}
                  onChange={handleChange}
                  required
                />
                <button
                  type="button"
                  className="location-btn"
                  onClick={getCurrentLocation}
                >
                  Use My Location
                </button>
              </div>
            </div>

            <div className="form-group">
              <label className="form-label">Choose Location on Map:</label>
              <MapComponent
                lat={coordinates.lat}
                lng={coordinates.lng}
                onLocationSelect={(lat, lng) => {
                  setCoordinates({ lat, lng });
                  setForm((f) => ({ ...f, latitude: lat, longitude: lng }));
                }}
              />
              {coordinates.lat && coordinates.lng && (
                <div style={{ fontSize: "0.9em", marginTop: 4 }}>
                  Selected: {coordinates.lat}, {coordinates.lng}
                </div>
              )}
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Area (sq ft)</label>
                <input
                  name="area"
                  type="number"
                  min="0"
                  placeholder="1500"
                  value={form.area}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label">Property Type</label>
                <select
                  name="propertyType"
                  value={form.propertyType}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select type</option>
                  <option>Apartment</option>
                  <option>Villa</option>
                  <option>Independent House</option>
                  <option>Duplex</option>
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Bedrooms</label>
                <select
                  name="bedrooms"
                  value={form.bedrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1, 2, 3, 4, 5].map((b) => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Bathrooms</label>
                <select
                  name="bathrooms"
                  value={form.bathrooms}
                  onChange={handleChange}
                  required
                >
                  <option value="">Select</option>
                  {[1, 2, 3, 4, 5].map((b) => (
                    <option key={b}>{b}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Year Built</label>
                <input
                  name="year"
                  type="number"
                  min="1900"
                  max={new Date().getFullYear()}
                  placeholder="2015"
                  value={form.year}
                  onChange={handleChange}
                />
              </div>
              <div className="form-group">
                <label className="form-label">Condition</label>
                <select
                  name="condition"
                  value={form.condition}
                  onChange={handleChange}
                >
                  <option value="">Select condition</option>
                  <option>Excellent</option>
                  <option>Good</option>
                  <option>Needs Renovation</option>
                </select>
              </div>
            </div>

            {/* Facilities */}
            {renderFacility("Hospital", "hospitalApplicable", "hospitalDistance")}
            {renderFacility("School", "schoolApplicable", "schoolDistance")}
            {renderFacility("Railway Station", "railwayApplicable", "railwayDistance")}
            {renderFacility("Bus Stand", "busApplicable", "busDistance")}

            <button className="predict-btn" type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict House Price"}
            </button>
          </form>
        </div>

        {/* Price Output */}
        <div className="price-prediction-card">
          <div className="price-header">
            <span className="price-icon">₹</span>
            <span className="price-title">Price Prediction</span>
          </div>
          <div className="price-desc">Your estimated house price will appear here</div>
          <div className="price-output">
            {!!result ? (
              <div className="price-result">
                <span className="result-value">₹ {result}</span>
              </div>
            ) : (
              <div className="result-placeholder">
                <span className="result-calc-icon">🧮</span>
                <span>Fill out the form to see your price prediction</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
